# D-RN-r4 edit record: every round-4a change to docs/DESIGN_FP_ARCH_RN.md, applied in place.
# Each anchor must occur exactly once (asserted); slices are bounded by two unique anchors.
# Usage: python3 apply_r4.py <path to DESIGN_FP_ARCH_RN.md>
import sys

P = sys.argv[1]
t = open(P, encoding='utf-8').read()
B4 = '[CURED 2026-10-18 (fp-final r4) — '
F4 = '[REFINED 2026-10-18 (fp-final r4) — '


def once(anchor):
    c = t.count(anchor)
    assert c == 1, (c, anchor[:120])


def after(anchor, add):
    global t
    once(anchor)
    t = t.replace(anchor, anchor + add, 1)


def before(anchor, add):
    global t
    once(anchor)
    t = t.replace(anchor, add + anchor, 1)


def swap(old, new):
    global t
    once(old)
    t = t.replace(old, new, 1)


def slice_swap(start, end, new, must=()):
    global t
    once(start)
    once(end)
    i = t.index(start)
    j = t.index(end) + len(end)
    assert i < j
    for m in must:
        assert m in t[i:j], m
    t = t[:i] + new + t[j:]


